sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // 1. Check if the test requires equipment
    var requiredModel = current.lab_test.required_equipment.toString();
    if (!requiredModel) {
        return; // Skip: no equipment required
    }

    var startGdt = new GlideDateTime(current.getValue('scheduled_start'));
    var endGdt = new GlideDateTime(current.getValue('scheduled_end'));
    if (!startGdt.isValid() || !endGdt.isValid() || endGdt.compareTo(startGdt) <= 0) {
        gs.addErrorMessage('Please provide a valid Scheduled Start and Scheduled End window.');
        current.setAbortAction(true);
        return;
    }

    var hospitalId = current.getValue('hospital');
    if (!hospitalId) {
        gs.addErrorMessage('Scheduling aborted: Hospital is required to validate or assign equipment.');
        current.setAbortAction(true);
        return;
    }

    var excludeId = current.isNewRecord() ? null : current.getUniqueValue();
    var service = new x_2223823_apollo_0.EquipmentAvailabilityService();

    // 2. If equipment is already populated (selected by user or retained on reschedule),
    // validate it strictly and NEVER silently overwrite it with another machine.
    if (!current.equipment.nil()) {
        var chosenEq = current.equipment.getRefRecord();
        var eqName = chosenEq.isValidRecord() ? chosenEq.getDisplayValue() : 'Selected equipment';
        var abortReason = '';

        if (!chosenEq.isValidRecord()) {
            abortReason = 'The selected equipment record no longer exists.';
        } else if (chosenEq.getValue('hospital') !== hospitalId) {
            abortReason = eqName + ' belongs to a different hospital than the lab test.';
        } else if (chosenEq.getValue('model') !== requiredModel) {
            abortReason = eqName + ' does not match the required equipment model for this test.';
        } else {
            // Reset failure reasons before direct isFree() check
            service.lastFailureReasons = [];
            if (!service.isFree(chosenEq, startGdt, endGdt, excludeId)) {
                abortReason = eqName + ' is unavailable (' + service.getFailureSummary() + ').';
            }
        }

        // Valid equipment: allow save without modifying current.equipment
        if (!abortReason) {
            return;
        }

        // Invalid equipment: block save, show exact reason, and suggest next free windows
        var altWindows = service.getNextFreeWindows(hospitalId, requiredModel, startGdt, endGdt, 3);
        var blockMsg = 'Unable to schedule test: ' + abortReason;
        blockMsg += ' Clear the Equipment field to allow automatic assignment.';

        if (altWindows.length > 0) {
            blockMsg += '<br/><b>Next available windows for this test:</b><ul><li>' + altWindows.join('</li><li>') + '</li></ul>';
        }

        gs.addErrorMessage(blockMsg);
        current.setAbortAction(true);
        return;
    }

    // 3. Auto-assignment path (only runs when current.equipment is empty)
    var candidates = service.getFreeCandidates(hospitalId, requiredModel, startGdt, endGdt, excludeId);

    // 4. Assign least loaded equipment and allow Scheduled status
    if (candidates.length > 0) {
        var selectedEqId = service.getLeastLoadedEquipment(candidates, startGdt);
        current.setValue('equipment', selectedEqId);
        // current.setValue('status', 'Scheduled');
        return;
    }

    // 5. Block save and provide failure reasons + next free windows
    var reasons = service.getFailureSummary();
    var nextWindows = service.getNextFreeWindows(hospitalId, requiredModel, startGdt, endGdt, 3);

    var msg = 'Unable to schedule test: ' + reasons + '.';
    if (nextWindows.length > 0) {
        msg += '<br/><b>Next available windows:</b><ul><li>' + nextWindows.join('</li><li>') + '</li></ul>';
    } else {
        msg += ' No free windows were found in the next 7 days.';
    }

    gs.addErrorMessage(msg);
    current.setAbortAction(true);

})(current, previous);
